-- Maze Quest's forest makeover: pick an explorer from the 8 characters and walk them from the camp tent to the cabin,
-- past glowing question lanterns. Run once in the Supabase SQL Editor (safe to run again).
update games set data = data || $j${"summary": "Pick your explorer from 8 characters, then walk them through 8 forest mazes from the camp tent to the cabin. Glowing lanterns ask a math or spelling question, and a right answer opens a shortcut.", "rules": ["Pick your explorer: tap the face on the level sign to choose from 8 characters.", "Arrow keys or W, A, S, D walk your explorer. The on-screen buttons work too.", "Keep walking the same way and you speed up.", "Start at the camp tent and find your way to the cabin.", "Walk up to a glowing lantern to pause the clock for a quick math or spelling question.", "Answer right and you jump ten squares along the real path.", "Stuck? Press Hint for an arrow pointing the right way.", "Finish all eight forests to see your time for each one on the leaderboard.", "Sound is on: press the speaker button to turn it off."], "minutes": 10, "vocabExample": "In Maze Quest, look ahead before you walk. Which turn gets you out fastest? That is a strategy."}$j$::jsonb
  || jsonb_build_object('cover', (data->'cover') || jsonb_build_object('alt', $a$Chike walks a forest maze of green hedges past glowing question lanterns, on the way from the camp tent to the cabin, in Maze Quest$a$::text)),
  updated_at = now()
where id = 'game-maze';
